    if (!activePosition) return;
    const question = saveQuestionFromCueCard(card);
    setPositions((items) =>
      items.map((position) =>
        position.id === activePosition.id ? { ...position, questions: [question, ...position.questions], updatedAt: nowIso() } : position,
      ),
    );
  };

  const updateMaterials = (materials: PositionMaterial[]) => {
    if (!activePosition) return;
    setPositions((items) =>
      items.map((position) =>
        position.id === activePosition.id
          ? {
              ...position,
              materials,
              analysisContext: createAnalysisContext(profile, position.job, position.matchReport, position.questions, materials),
              updatedAt: nowIso(),
